export async function chargeOrder(orderId: string, deps: Deps): Promise<Receipt> {
  const order = await deps.orders.get(orderId);
  if (!order) throw new NotFoundError(`order ${orderId}`);
  const intent = await deps.payments.createIntent({
    amount: order.total,
    currency: order.currency,
    idempotencyKey: order.id,
  });
  return { orderId, intentId: intent.id, status: intent.status };
}

interface RetryOptions {
  attempts: number;
  baseDelayMs: number;
  maxDelayMs?: number;
}

export async function withRetry<T>(
  fn: () => Promise<T>,
  { attempts, baseDelayMs, maxDelayMs = 10_000 }: RetryOptions,
): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      const delay = Math.min(baseDelayMs * 2 ** i, maxDelayMs);
      await new Promise<void>((resolve) => setTimeout(resolve, delay));
    }
  }
  throw lastError;
}

