const kafka = new Kafka({ clientId: "billing", brokers: process.env.BROKERS.split(",") });
const consumer = kafka.consumer({ groupId: "billing-invoices" });

async function run() {
  await consumer.connect();
  await consumer.subscribe({ topic: "orders.paid", fromBeginning: false });

  await consumer.run({
    eachMessage: async ({ topic, partition, message }) => {
      const order = JSON.parse(message.value.toString());
      try {
        await createInvoice(order);
      } catch (err) {
        console.error(`invoice failed for ${order.id}`, err);
        await deadLetter.send({ topic: "orders.paid.dlq", messages: [message] });
      }
    },
  });
}

