[HttpPost("{id:guid}/cancel")]
public async Task<IActionResult> Cancel(Guid id, CancellationToken ct)
{
    var order = await _orders.FindAsync(id, ct);
    if (order is null) return NotFound();
    order.Cancel(_clock.UtcNow);
    await _orders.SaveAsync(order, ct);
    return NoContent();
}

public sealed class CreateOrderHandler : IRequestHandler<CreateOrder, OrderDto>
{
    private readonly AppDbContext _db;
    private readonly IClock _clock;
    private readonly ILogger<CreateOrderHandler> _logger;

    public CreateOrderHandler(AppDbContext db, IClock clock, ILogger<CreateOrderHandler> logger)
    {
        _db = db;
        _clock = clock;
        _logger = logger;
    }

    public async Task<OrderDto> Handle(CreateOrder request, CancellationToken ct)
    {
        var order = Order.Create(request.CustomerId, request.Lines, _clock.UtcNow);
        _db.Orders.Add(order);
        await _db.SaveChangesAsync(ct);
        _logger.LogInformation("Order {OrderId} created for {CustomerId}", order.Id, order.CustomerId);
        return order.ToDto();
    }
}

