from dataclasses import dataclass
from datetime import datetime, timedelta


@dataclass
class Lease:
    key: str
    owner: str
    expires_at: datetime

    def expired(self, now: datetime) -> bool:
        return now >= self.expires_at


class LeaseStore:
    def __init__(self, ttl_seconds: int = 30):
        self._leases: dict[str, Lease] = {}
        self._ttl = timedelta(seconds=ttl_seconds)

    def acquire(self, key: str, owner: str) -> bool:
        now = datetime.utcnow()
        current = self._leases.get(key)
        if current and not current.expired(now) and current.owner != owner:
            return False
        self._leases[key] = Lease(key, owner, now + self._ttl)
        return True

@Service
public class PriceService {
    private final DiscountRepository discounts;

    public BigDecimal priceFor(Order order) {
        return discounts.findActive(order.getCustomerId())
                .map(d -> order.getSubtotal().multiply(BigDecimal.ONE.subtract(d.getRate())))
                .orElse(order.getSubtotal());
    }
}

@Entity
@Table(name = "orders")
public class Order {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String customerId;

    @Enumerated(EnumType.STRING)
    private OrderStatus status = OrderStatus.PENDING;

    @OneToMany(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<OrderLine> lines = new ArrayList<>();

    public BigDecimal total() {
        return lines.stream()
                .map(OrderLine::subtotal)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}

use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;

#[derive(Clone, Default)]
pub struct Cache {
    inner: Arc<RwLock<HashMap<String, Vec<u8>>>>,
}

impl Cache {
    pub async fn get(&self, key: &str) -> Option<Vec<u8>> {
        self.inner.read().await.get(key).cloned()
    }

    pub async fn put(&self, key: impl Into<String>, value: Vec<u8>) {
        let mut guard = self.inner.write().await;
        guard.insert(key.into(), value);
    }

    pub async fn len(&self) -> usize {
        self.inner.read().await.len()
    }
}

struct RateLimiter {
    bool allow(const std::string& key) {
        std::lock_guard<std::mutex> lock(mu);
        return ++counts[key] <= limit;
    }
    std::size_t limit = 100;
    std::unordered_map<std::string, std::size_t> counts;
    std::mutex mu;
};

