func main() {
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	srv := &http.Server{Addr: ":8080", Handler: routes()}
	go func() {
		if err := srv.ListenAndServe(); err != http.ErrServerClosed {
			log.Fatalf("listen: %v", err)
		}
	}()

	<-ctx.Done()
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		log.Printf("shutdown: %v", err)
	}
}

class OrderService(private val repo: OrderRepository) {
    suspend fun cancel(id: UUID): Order {
        val order = repo.find(id) ?: throw NotFoundException("order $id")
        check(order.status == Status.PENDING) { "cannot cancel ${order.status}" }
        return repo.save(order.copy(status = Status.CANCELLED))
    }
}

